def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    pts=[(r,c) for r in range(h) for c in range(w) if out[r][c]==2]
    # Between repeated diamond motifs, connect corresponding vertices along rows/columns.
    # A diamond consists of a central horizontal row of three 2s and top/bottom apexes.
    centers=[]
    for r in range(h):
        for c in range(1,w-1):
            if out[r][c]==0 and out[r][c-1]==2 and out[r][c+1]==2 and r>0 and r+1<h and out[r-1][c]==2 and out[r+1][c]==2:
                centers.append((r,c))
    # Connect horizontal facing diamonds: same row, nearest outer vertices.
    for r,c in centers:
        for rr,cc in centers:
            if rr==r and cc>c and all(out[r][x]==0 for x in range(c+2,cc-1)):
                # connect right vertex of left diamond to left vertex of right diamond
                for x in range(c+2,cc-1): out[r][x]=1
    # Connect vertically aligned diamond apex/vertices where a motif's bottom apex and another's top apex align.
    for r,c in centers:
        # find uninterrupted line of zeroes above/below, bounded by 2
        for dr in (-1,1):
            rr=r+2*dr
            while 0<=rr<h and out[rr][c]==0: rr+=dr
            if 0<=rr<h and out[rr][c]==2:
                x=r+dr
                while x!=rr:
                    out[x][c]=1; x+=dr
    return out
